"""MPS MoE kernels — Moondream 3 weight-only FP8, compact routing.

Moondream 3's MoE is weight-only FP8 e4m3: expert weights are uint8-packed
``[E, N, K]`` with per-output-channel fp32 scales ``[E, N]``; activations stay
bf16 / fp16. For larger token counts, the MPS forward is five Metal dispatches:

  1. ``moe_route_compact``: ``topk_ids → sorted_token_ids`` (dense permutation
     grouped by expert, no per-expert padding) + ``rhs_indices`` (expert id
     per row). Computed once and shared by the up and down GEMMs.
  2. up GEMM (``moe_fp8_gemm_into``): route_a gather → FP8 gather-MM with the
     per-N scale epilogue → unsort, into ``up_out[M, top_k, 2*I]``.
  3. ``gelu_residual`` (GEGLU): ``up_out → down_in[M*top_k, I]``.
  4. down GEMM: same route, into ``down_out[M, top_k, H]`` with the
     ``topk_weights`` multiply folded in.
  5. ``moe_sum``: reduce over top_k → ``fused[M, H]``.

For small decode batches, the base up/down projections use direct FP8 GEMV
kernels over ``topk_ids`` instead. That bypasses route construction, route_a
gather, and unsort; larger batches stay on the Steel gather-GEMM path where
tiled reuse wins. The cutoff follows MLX's architecture-aware qmv/qmm branching
and is calibrated for the Moondream 3 shapes on ayanami (Apple M2).

The MoE handle is selected in ``kestrel_kernels.moe.dispatch`` and exposed
through the package's public MoE API.

Routed multi-adapter LoRA is supported when the handle is prepared with
``max_loras > 0``: a per-adapter compact route feeds two low-rank gather-MMs
(shrink hidden→rank, expand rank→out) whose delta is scatter-added into the base
up/down output — fp16 LoRA weights, cost proportional to rank, zero overhead
when no adapter is active.

Out of scope on MPS (raise, don't silently degrade):
- Non-FP8 expert weights (fp16 / bf16 / fp32). Moondream 3 ships FP8.
- Activation FP8 quantization (``a_fp8_bits`` / ``a_fp8_scale``).
- ``base_up_out`` LoRA capture (training-only).
"""

from __future__ import annotations

from dataclasses import dataclass

import torch

# Trigger native extension load (the FP8 path dispatches Metal kernels).
from kestrel_kernels.mps import _native

from kestrel_kernels.gelu_residual.fallback import gelu_residual_torch_into
from kestrel_kernels.moe_sum_ops.fallback import moe_sum_torch
from kestrel_kernels.moe.api import (
    MoeCapacity,
    MoeExpertWeights,
    MoeLoraState,
    MoeSpec,
)
from kestrel_kernels.moe.workspace import FixedWorkspaceBuffer


# Performance cutoff for Moondream 3 MPS decode shapes, measured on ayanami
# (Apple M2). MLX also treats qmv/qmm switching as device-family dependent, so
# keep this below the noisy crossover rather than pushing to the last winning M.
# MPS block_m / tile picker: ``8`` for decode (M ≤ 32), ``64`` for mid /
# prefill. Picks the FP8 gather GEMM tile variant (see ``pick_fp8_variant`` in
# mps_ops.mm) and the compact route's tail-padding multiple. up and down share
# one block_m by construction (one handle → one value).
def _pick_block_m(num_tokens: int) -> int:
    return 8 if num_tokens <= 32 else 64


def _mprime(num_valid: int, block_m: int, num_experts: int, pad_experts: bool) -> int:
    """Padded row count = GEMM M-tile extent. Mirrors ``moe_compact_mprime`` in
    mps_ops.mm exactly (route + GEMM must agree). ``pad_experts`` (prefill)
    reserves ``block_m - 1`` slack per expert so each aligns to a tile;
    otherwise it just rounds the dense total up (decode)."""
    rows = num_valid + num_experts * (block_m - 1) if pad_experts else num_valid
    return ((rows + block_m - 1) // block_m) * block_m


def _round_up(x: int, multiple: int) -> int:
    return ((x + multiple - 1) // multiple) * multiple


def _max_lora_mprime(
    max_tokens: int, top_k: int, num_experts: int, max_loras: int,
    block_m: int, pad_experts: bool,
) -> int:
    """Worst-case LoRA route extent. The route concatenates per-adapter compact
    routes; under pad_experts (prefill) each of up to ``max_loras`` adapters can
    pad each expert by ``block_m - 1``. Decode (pad_experts=False) is dense."""
    rows = max_tokens * top_k
    if pad_experts:
        rows += max_loras * num_experts * (block_m - 1)
    return _round_up(rows, block_m)


def moe_sum_mps(inp: torch.Tensor, out: torch.Tensor) -> None:
    moe_sum_torch(inp, out)


def gelu_residual_cute_mps(out: torch.Tensor, inp: torch.Tensor) -> None:
    # MD3's FP8 MoE up-weight is stored in the 8-row gate/up interleave by the (device-agnostic)
    # engine loader (kestrel _moe_layout.build_md3_moe_up_slab), so up_out lands interleaved on
    # Mac exactly as on CUDA. Read the interleave (matches the CUDA compact gated-GELU's
    # unconditional interleaved=True) -- half-split here would mis-pair gate/up and corrupt.
    gelu_residual_torch_into(out=out, inp=inp, interleaved=True)


def topk_fwd_mps(
    x: torch.Tensor,
    k: int,
    softmax: bool = False,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Fused topk + softmax + int32 cast on MPS via Metal kernel.

    Mirrors the CUDA ``topk_bfloat16_n64_k8_softmax`` cubin's contract:
    ``[M, 64]`` bf16 / fp16 in, ``([M, 8] same-dtype, [M, 8] int32)`` out.
    Saves 3-4 torch dispatches per MoE layer (torch.topk + F.softmax +
    .to(int32)) — measurable on decode where each MoE forward fires
    once per layer.

    Falls back to the torch reference when shape / dtype / k / softmax
    don't match the Metal kernel's lock.
    """
    fast_path = (
        x.device.type == "mps"
        and x.is_contiguous()
        and x.ndim == 2
        and x.size(1) == 64
        and k == 8
        and softmax
        and x.dtype == torch.float16
    )
    if not fast_path:
        return _topk_torch_fallback(x, k, softmax=softmax)

    M = x.size(0)
    values = torch.empty((M, k), dtype=x.dtype, device=x.device)
    indices = torch.empty((M, k), dtype=torch.int32, device=x.device)
    _native.ops.moe_topk_softmax_into(x, values, indices)
    return values, indices


def _topk_torch_fallback(
    x: torch.Tensor, k: int, softmax: bool,
) -> tuple[torch.Tensor, torch.Tensor]:
    values, indices = torch.topk(x, k=k, dim=-1)
    if softmax:
        values = torch.softmax(values.float(), dim=-1).to(x.dtype)
    return values, indices.to(torch.int32)


def moe_route_compact_mps(
    topk_ids: torch.Tensor,
    *,
    num_experts: int,
    block_m: int,
    pad_experts: bool,
    sorted_token_ids: torch.Tensor,
    rhs_indices: torch.Tensor,
) -> None:
    """Compact MoE routing on MPS (replaces the block-padded align).

    ``topk_ids`` is the int32 ``[M, top_k]`` (or flat ``[M*top_k]``) routing
    table. Writes the permutation into ``sorted_token_ids`` (slot value
    ``token*top_k + k_slot`` grouped by expert) and the per-row expert id into
    ``rhs_indices``; rows past the active region (up to the padded extent) are
    sentinel-filled. ``pad_experts`` aligns each expert to a ``block_m`` tile
    (prefill); otherwise the layout is dense (decode). Both outputs are int32
    (``rhs_indices`` is read as uint32 by the gather GEMM — same bit pattern;
    the UINT32_MAX sentinel is -1).
    """
    _native.ops.moe_route_compact_into(
        topk_ids,
        sorted_token_ids,
        rhs_indices,
        int(num_experts),
        int(block_m),
        bool(pad_experts),
    )


def _fp8_weight_as_uint8(weight: torch.Tensor, name: str) -> torch.Tensor:
    if weight.dtype == torch.uint8:
        return weight
    if weight.dtype == torch.float8_e4m3fn:
        return weight.view(torch.uint8)
    raise NotImplementedError(
        "kestrel-kernels MPS MoE is FP8-only: expert weights must be uint8 "
        f"(FP8 e4m3 packed) or float8_e4m3fn; got {name}={weight.dtype}."
    )


def _invoke_fp8_gemm_compact(
    A: torch.Tensor,
    B_uint8: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    rhs_indices: torch.Tensor,
    topk_weights: torch.Tensor | None,
    mul_routed_weight: bool,
    top_k: int,
    block_m: int,
    pad_experts: bool,
) -> None:
    """Weight-FP8 gather GEMM over a compact route. Writes ``C`` in place.

    ``C`` has shape ``[M, top_k, N]``; each (token, k_slot) row receives
    ``A[token] @ dequant(B[expert])`` (× ``topk_weights`` when
    ``mul_routed_weight``). Slots not written by the unsort kernel stay zero,
    so ``C`` is pre-zeroed here.
    """
    if mul_routed_weight and topk_weights is None:
        raise ValueError(
            "invoke_moe_gemm: mul_routed_weight=True requires topk_weights"
        )
    # The unsort kernel reads topk_weights through the same typed loader as A,
    # so coerce to A's dtype at the boundary (callers commonly pass fp32
    # straight from softmax). Cost is negligible — shape [M, top_k].
    if topk_weights is not None and topk_weights.dtype != A.dtype:
        topk_weights = topk_weights.to(A.dtype)
    C.zero_()
    _native.ops.moe_fp8_gemm_into(
        C, A, B_uint8, B_scale,
        topk_weights,
        sorted_token_ids, rhs_indices,
        int(top_k), int(block_m),
        bool(pad_experts), bool(mul_routed_weight),
    )


def _invoke_fp8_gemv_decode(
    A: torch.Tensor,
    B_uint8: torch.Tensor,
    B_scale: torch.Tensor,
    C: torch.Tensor,
    *,
    topk_ids: torch.Tensor,
    topk_weights: torch.Tensor | None,
    mul_routed_weight: bool,
    top_k: int,
    a_per_assignment: bool,
) -> None:
    """Small-decode direct GEMV over ``topk_ids``.

    This bypasses compact route construction, route_a gather, and unsort. It is
    faster for very small decode batches, but scales linearly with routed
    assignments, so larger batches stay on the Steel gather-GEMM path.
    """
    if mul_routed_weight and topk_weights is None:
        raise ValueError(
            "invoke_moe_gemv_decode: mul_routed_weight=True requires topk_weights"
        )
    if topk_weights is not None and topk_weights.dtype != A.dtype:
        topk_weights = topk_weights.to(A.dtype)
    _native.ops.moe_fp8_gemv_decode_into(
        C, A, B_uint8, B_scale, topk_ids,
        topk_weights,
        int(top_k), bool(mul_routed_weight), bool(a_per_assignment),
    )


def _lora_weight_as_fp16(weight: torch.Tensor, name: str) -> torch.Tensor:
    if weight.dtype == torch.float16:
        return weight
    raise NotImplementedError(
        "kestrel-kernels MPS MoE LoRA requires fp16 LoRA weights "
        f"(matching the resolved MPS activation dtype); got {name}={weight.dtype}."
    )


def moe_lora_route_compact_mps(
    topk_ids: torch.Tensor,
    *,
    active_token_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    active_lora_ids: torch.Tensor,
    num_experts: int,
    block_m: int,
    pad_experts: bool,
    num_tokens: int,
    top_k: int,
    sorted_token_ids: torch.Tensor,
    rhs_indices: torch.Tensor,
) -> None:
    """Per-adapter LoRA routing: concatenated compact route over the active
    assignments, keyed by ``group = lora_id*num_experts + expert``. ``slot =
    token*top_k + k_slot`` (global). Tail/inactive rows are sentinel-filled."""
    _native.ops.moe_lora_route_compact_into(
        topk_ids,
        active_token_ids,
        active_lora_meta,
        active_lora_ids,
        sorted_token_ids,
        rhs_indices,
        int(num_tokens),
        int(top_k),
        int(num_experts),
        int(block_m),
        bool(pad_experts),
    )


def _lora_shrink(
    scratch: torch.Tensor,
    x: torch.Tensor,
    lora_a: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    rhs_indices: torch.Tensor,
    lora_ranks: torch.Tensor | None,
    num_experts: int,
    top_k: int,
    block_m: int,
) -> None:
    # route_a gathers x by the LoRA route, then x_sorted @ lora_a[group].T →
    # scratch (routed, plain store). ``top_k`` controls the A gather: top_k for
    # up (gather x by token = slot//top_k), 1 for down (down_in row == slot).
    # When ``lora_ranks`` (per-adapter logical rank) is given, the shrink also
    # zeros scratch columns beyond each row's adapter rank, so mixed-rank
    # batches stay correct even though the GEMM runs at the shared rank width.
    _native.ops.moe_lora_shrink_into(
        scratch, x, lora_a, sorted_token_ids, rhs_indices,
        lora_ranks, int(num_experts), int(top_k), int(block_m),
    )


def _lora_expand(
    base: torch.Tensor,
    scratch: torch.Tensor,
    lora_b: torch.Tensor,
    *,
    sorted_token_ids: torch.Tensor,
    rhs_indices: torch.Tensor,
    topk_weights: torch.Tensor | None,
    top_k: int,
    block_m: int,
    mul_routed_weight: bool,
) -> None:
    # scratch @ lora_b[group].T → delta, scatter-added into base[token, k_slot]
    # (× topk_weight for the down projection). ``top_k`` is the routing top_k:
    # base is [M, top_k, out], so the unsort recovers (token, k_slot) from slot.
    if mul_routed_weight and topk_weights is not None and topk_weights.dtype != base.dtype:
        topk_weights = topk_weights.to(base.dtype)
    _native.ops.moe_lora_expand_into(
        base, scratch, lora_b, sorted_token_ids, rhs_indices,
        topk_weights if mul_routed_weight else None,
        int(top_k), int(block_m), bool(mul_routed_weight),
    )


@dataclass(frozen=True)
class _CompactMpsRoute:
    sorted_token_ids: torch.Tensor   # [max_mprime] int32
    rhs_indices: torch.Tensor        # [max_mprime] int32 (read as uint32)


@dataclass
class _CompactMpsWorkspace:
    up: FixedWorkspaceBuffer
    activation: FixedWorkspaceBuffer
    down: FixedWorkspaceBuffer
    output: FixedWorkspaceBuffer


@dataclass
class _CompactMpsLoraWorkspace:
    # Per-adapter route (group = lora_id*E + expert) over the active
    # assignments, sized to the worst-case padded extent; reused for up + down.
    route_sorted: torch.Tensor   # [max_mprime] int32
    route_rhs: torch.Tensor      # [max_mprime] int32 (read as uint32)
    scratch: FixedWorkspaceBuffer  # [max_mprime, max_rank] fp16 (shrink output)
    max_mprime: int


@dataclass
class CompactMpsMoeImpl:
    """Compact-routing FP8 MoE forward on Apple Silicon.

    Mirrors the CUDA compact path's structure (route once, reuse for up/down)
    but stays weight-FP8 with bf16/fp16 activations — no activation quant, no
    LoRA. Selected for ``device.type == "mps"`` in ``moe.dispatch``.
    """

    spec: MoeSpec
    capacity: MoeCapacity
    device: torch.device
    block_m: int
    pad_experts: bool
    route: _CompactMpsRoute
    workspace: _CompactMpsWorkspace
    lora_ws: _CompactMpsLoraWorkspace | None = None
    decode_gemv_max_tokens: int = 0

    def forward(
        self,
        *,
        x: torch.Tensor,
        topk_ids: torch.Tensor,
        topk_weights: torch.Tensor,
        weights: MoeExpertWeights,
        out: torch.Tensor | None,
        lora: MoeLoraState | None = None,
        base_up_out: torch.Tensor | None = None,
    ) -> torch.Tensor:
        if base_up_out is not None:
            raise NotImplementedError(
                "base_up_out (LoRA capture) is not supported on MPS"
            )
        if lora is not None and self.lora_ws is None:
            raise RuntimeError(
                "MoE handle was prepared without LoRA capacity; prepare with "
                "max_loras > 0 to use LoRA on MPS"
            )
        if lora is not None:
            self._validate_lora_capacity(lora)

        spec = self.spec
        if x.device.type != "mps":
            raise ValueError("MPS MoE requires MPS tensors")
        if x.ndim != 2 or x.shape[1] != spec.hidden_size:
            raise ValueError(
                f"x must have shape [tokens, {spec.hidden_size}], "
                f"got {tuple(x.shape)}"
            )
        if not x.is_contiguous():
            raise ValueError("x must be contiguous")
        num_tokens = int(x.shape[0])
        # Decode handles are prepared for one fixed token count (CUDA-graph /
        # bucket shape); reusing one for a different count is a caller bug.
        # Match the CUDA / legacy impls' exact-shape check rather than silently
        # succeeding on MPS.
        if self.capacity.mode == "decode" and num_tokens != self.capacity.max_tokens:
            raise RuntimeError(
                f"MoE handle token shape mismatch: got {num_tokens} tokens, "
                f"prepared for {self.capacity.max_tokens}. Prepare one handle "
                "per CUDA graph/bucket shape."
            )
        if num_tokens > self.capacity.max_tokens:
            raise RuntimeError(
                f"MoE handle capacity overflow: got {num_tokens} tokens, "
                f"capacity is {self.capacity.max_tokens}"
            )
        if spec.weight_format != "fp8_e4m3":
            raise NotImplementedError(
                "kestrel-kernels MPS MoE is FP8-only; got weight_format="
                f"{spec.weight_format!r}"
            )
        up_weight = _fp8_weight_as_uint8(weights.up, "up")
        down_weight = _fp8_weight_as_uint8(weights.down, "down")
        if weights.up_scale is None or weights.down_scale is None:
            raise ValueError("FP8 MoE weights require up_scale and down_scale")

        if num_tokens == 0:
            return self._output(x, out, num_tokens)

        if topk_ids.shape != (num_tokens, spec.top_k):
            raise ValueError(
                f"topk_ids must have shape [{num_tokens}, {spec.top_k}]"
            )
        if topk_ids.dtype != torch.int32 or not topk_ids.is_contiguous():
            raise ValueError("topk_ids must be contiguous int32")
        # The down GEMM flattens topk_weights with ``view(-1)`` and the unsort
        # kernel indexes it as ``token*top_k + k_slot``. A wrong layout (e.g. a
        # contiguous [top_k, num_tokens] or stale flat scratch with the right
        # element count) would silently weight the wrong routed outputs, so
        # pin the exact [num_tokens, top_k] contiguous shape here.
        if topk_weights.shape != (num_tokens, spec.top_k):
            raise ValueError(
                f"topk_weights must have shape [{num_tokens}, {spec.top_k}]"
            )
        if not topk_weights.is_contiguous():
            raise ValueError("topk_weights must be contiguous")

        block_m = self.block_m
        pad_experts = self.pad_experts
        use_decode_gemv = (
            block_m == 8
            and not pad_experts
            and num_tokens <= self.decode_gemv_max_tokens
            and hasattr(_native.ops, "moe_fp8_gemv_decode_into")
        )

        sorted_token_ids = None
        rhs_indices = None
        if not use_decode_gemv:
            num_valid = num_tokens * spec.top_k
            mprime = _mprime(num_valid, block_m, spec.num_experts, pad_experts)
            sorted_token_ids = self.route.sorted_token_ids[:mprime]
            rhs_indices = self.route.rhs_indices[:mprime]
            moe_route_compact_mps(
                topk_ids,
                num_experts=spec.num_experts,
                block_m=block_m,
                pad_experts=pad_experts,
                sorted_token_ids=sorted_token_ids,
                rhs_indices=rhs_indices,
            )

        # LoRA shares one per-adapter route across up + down (computed once).
        # Skip the whole LoRA path (route + shrink/expand) when no adapter is
        # active, so an all-inactive batch takes the unchanged base path at zero
        # overhead. ``active_lora_ids.numel()`` is the active-adapter count for
        # the default (non-fixed-capacity) metadata — host-side, no GPU sync, and
        # never a false skip (it can only undercount to 0 when truly empty). In
        # fixed-capacity metadata it is the reserved max (never 0), so we keep
        # running the no-op dispatches there, matching CUDA's deliberate
        # fixed-shape no-op launch (``grid_z = max(1, active_lora_ids.numel())``
        # in moe/lora/cute.py); MPS has no graph capture, so the eager skip is
        # safe and output-identical.
        lora_route = None
        lora_ranks_t = None
        # ``active_lora_max_rank == 0`` (with active adapters declared) is CUDA's
        # ``_rank_limit`` zero-clamp: the delta is skipped entirely, so callers
        # get the base output. Treat it like no-active here so we take the
        # unchanged base path instead of dispatching no-op LoRA work.
        lora_active = (
            lora is not None
            and int(lora.metadata.active_lora_ids.numel()) > 0
            and lora.metadata.active_lora_max_rank != 0
        )
        if lora_active:
            lora_route = self._build_lora_route(topk_ids, lora, num_tokens)
            # Per-adapter logical ranks (int32, indexed by adapter id). When
            # given, the shrink masks each row's scratch columns beyond its
            # adapter's rank so mixed-rank batches are correct (CUDA parity);
            # None means every active adapter uses the full stored rank.
            lora_ranks_t = lora.lora_ranks
            if lora_ranks_t is not None:
                num_loras = lora.up_a.shape[0] // spec.num_experts
                if lora_ranks_t.dtype != torch.int32 or lora_ranks_t.numel() < num_loras:
                    raise ValueError(
                        "MoeLoraState.lora_ranks must be int32 with length >= "
                        "num_loras (one logical rank per adapter)"
                    )
            elif lora.metadata.active_lora_max_rank is not None:
                # No per-adapter ranks given, but the metadata declares an active
                # max smaller than the stored rank — mirror CUDA's coarse clamp
                # (``_rank_limit`` in moe/lora/cute.py) by synthesizing a uniform
                # per-adapter rank tensor at ``active_lora_max_rank`` so the
                # shrink mask zeros scratch[m, active_max:storage] for every row.
                # Without this, weight rows beyond active_max (which may be
                # non-zero padding) would leak into the delta on MPS only.
                storage_max = max(int(lora.up_a.shape[1]), int(lora.down_a.shape[1]))
                active_max = int(lora.metadata.active_lora_max_rank)
                if 0 < active_max < storage_max:
                    num_loras = lora.up_a.shape[0] // spec.num_experts
                    lora_ranks_t = torch.full(
                        (num_loras,), active_max, dtype=torch.int32,
                        device=lora.up_a.device,
                    )

        # ----- up projection: x @ up_weight (gate+up stacked on N=2*I).
        up_out = self.workspace.up.get(
            (num_tokens, spec.top_k, spec.intermediate_size * 2),
            device=x.device,
            dtype=x.dtype,
        )
        if use_decode_gemv:
            _invoke_fp8_gemv_decode(
                x, up_weight, weights.up_scale, up_out,
                topk_ids=topk_ids,
                topk_weights=None,
                mul_routed_weight=False,
                top_k=spec.top_k,
                a_per_assignment=False,
            )
        else:
            assert sorted_token_ids is not None and rhs_indices is not None
            _invoke_fp8_gemm_compact(
                x, up_weight, weights.up_scale, up_out,
                sorted_token_ids=sorted_token_ids,
                rhs_indices=rhs_indices,
                topk_weights=None,
                mul_routed_weight=False,
                top_k=spec.top_k,
                block_m=block_m,
                pad_experts=pad_experts,
            )

        # ----- LoRA up delta: up_out += (x @ up_a) @ up_b, before the GEGLU.
        if lora_route is not None:
            lora_sorted, lora_rhs = lora_route
            up_scratch = self._lora_scratch(lora.up_a.shape[1], x.device, spec.dtype)
            _lora_shrink(
                up_scratch, x, _lora_weight_as_fp16(lora.up_a, "up_a"),
                sorted_token_ids=lora_sorted, rhs_indices=lora_rhs,
                lora_ranks=lora_ranks_t, num_experts=spec.num_experts,
                top_k=spec.top_k, block_m=block_m,
            )
            _lora_expand(
                up_out, up_scratch, _lora_weight_as_fp16(lora.up_b, "up_b"),
                sorted_token_ids=lora_sorted, rhs_indices=lora_rhs,
                topk_weights=None, top_k=spec.top_k, block_m=block_m,
                mul_routed_weight=False,
            )

        # ----- GEGLU activation: gelu(gate) * (up + 1) → [M*top_k, I].
        down_in = self.workspace.activation.get(
            (num_tokens * spec.top_k, spec.intermediate_size),
            device=x.device,
            dtype=x.dtype,
        )
        gelu_residual_cute_mps(
            down_in, up_out.view(num_tokens * spec.top_k, -1)
        )

        # ----- down projection: down_in @ down_weight, with topk weighting.
        # A is [M*top_k, I] indexed per assignment (top_k=1 → token == slot).
        down_out = self.workspace.down.get(
            (num_tokens, spec.top_k, spec.hidden_size),
            device=x.device,
            dtype=x.dtype,
        )
        # The unsort kernel indexes topk_weights flat by ``slot`` (= token *
        # top_k + k_slot). With top_k=1 here, pass the flattened
        # ``[M*top_k]`` view so each assignment row reads its own weight.
        # ``view`` (not ``reshape``) keeps this metadata-only — it raises
        # instead of launching an MPS copy if topk_weights is ever
        # non-contiguous, which the gather GEMM requires anyway.
        if use_decode_gemv:
            _invoke_fp8_gemv_decode(
                down_in, down_weight, weights.down_scale, down_out,
                topk_ids=topk_ids,
                topk_weights=topk_weights,
                mul_routed_weight=True,
                top_k=spec.top_k,
                a_per_assignment=True,
            )
        else:
            assert sorted_token_ids is not None and rhs_indices is not None
            _invoke_fp8_gemm_compact(
                down_in, down_weight, weights.down_scale, down_out,
                sorted_token_ids=sorted_token_ids,
                rhs_indices=rhs_indices,
                topk_weights=topk_weights.view(-1),
                mul_routed_weight=True,
                top_k=1,
                block_m=block_m,
                pad_experts=pad_experts,
            )

        # ----- LoRA down delta: down_out += topk * ((down_in @ down_a) @ down_b),
        # before the top_k reduction. Shrink gathers down_in per assignment
        # (top_k=1 → row == slot); expand scatters to down_out[token, k_slot].
        if lora_route is not None:
            lora_sorted, lora_rhs = lora_route
            down_scratch = self._lora_scratch(lora.down_a.shape[1], x.device, spec.dtype)
            _lora_shrink(
                down_scratch, down_in, _lora_weight_as_fp16(lora.down_a, "down_a"),
                sorted_token_ids=lora_sorted, rhs_indices=lora_rhs,
                lora_ranks=lora_ranks_t, num_experts=spec.num_experts,
                top_k=1, block_m=block_m,
            )
            _lora_expand(
                down_out, down_scratch, _lora_weight_as_fp16(lora.down_b, "down_b"),
                sorted_token_ids=lora_sorted, rhs_indices=lora_rhs,
                topk_weights=topk_weights, top_k=spec.top_k, block_m=block_m,
                mul_routed_weight=True,
            )

        # ----- reduce over top_k experts → [M, H].
        fused = self._output(x, out, num_tokens)
        moe_sum_mps(down_out, fused)
        return fused

    def _output(
        self, x: torch.Tensor, out: torch.Tensor | None, num_tokens: int
    ) -> torch.Tensor:
        shape = (num_tokens, self.spec.hidden_size)
        if out is None:
            fused = self.workspace.output.get(
                shape, device=x.device, dtype=x.dtype
            )
            if num_tokens == 0:
                fused.zero_()
            return fused
        if (
            tuple(out.shape) != shape
            or out.device != x.device
            or out.dtype != x.dtype
            or not out.is_contiguous()
        ):
            raise ValueError(
                f"out must be contiguous {x.dtype} with shape {shape}"
            )
        if num_tokens == 0:
            out.zero_()
        return out

    def _validate_lora_capacity(self, lora: MoeLoraState) -> None:
        """Reject states that exceed the prepared LoRA capacity, matching the
        CUDA compact/warpgemv backends (``_validate_lora_capacity``) so the
        public capacity contract isn't backend-dependent."""
        weight_loras = int(lora.up_a.shape[0]) // self.spec.num_experts
        if weight_loras > self.capacity.max_loras:
            raise RuntimeError(
                f"MoE LoRA capacity overflow: got {weight_loras} LoRAs, "
                f"capacity is {self.capacity.max_loras}"
            )
        max_rank = max(int(lora.up_a.shape[1]), int(lora.down_a.shape[1]))
        if max_rank > self.capacity.max_lora_rank:
            raise RuntimeError(
                f"MoE LoRA rank overflow: got rank {max_rank}, "
                f"capacity is {self.capacity.max_lora_rank}"
            )

    def _build_lora_route(self, topk_ids, lora, num_tokens):
        """Per-adapter LoRA route (sorted_token_ids + rhs group ids), shared by
        the up and down GEMMs. Sized to the workspace's worst-case extent; GEMMs
        skip the sentinel tail. Group = lora_id*num_experts + expert (selects the
        weight plane). The shrink scratch is sized per projection in forward."""
        ws = self.lora_ws
        assert ws is not None
        spec = self.spec
        mprime = ws.max_mprime
        sorted_ids = ws.route_sorted[:mprime]
        rhs = ws.route_rhs[:mprime]
        meta = lora.metadata
        moe_lora_route_compact_mps(
            topk_ids,
            active_token_ids=meta.active_token_ids,
            active_lora_meta=meta.active_lora_meta,
            active_lora_ids=meta.active_lora_ids,
            num_experts=spec.num_experts,
            block_m=self.block_m,
            # Dense (no per-expert padding) even at prefill: the LoRA weight
            # planes are tiny (rank≤64), so tile-straddling B-reloads are cheap
            # — unlike the base FP8 GEMM, the per-expert alignment padding would
            # only bloat the gather/scatter over mostly-empty rows.
            pad_experts=False,
            num_tokens=num_tokens,
            top_k=spec.top_k,
            sorted_token_ids=sorted_ids,
            rhs_indices=rhs,
        )
        return sorted_ids, rhs

    def _lora_scratch(self, rank: int, device, dtype) -> torch.Tensor:
        """Shrink scratch sized to one projection's stored rank. Up and down
        reuse the single reserved buffer (up is fully consumed by its expand
        before the down shrink overwrites it), so the two projections can use
        independent ranks — matching the CUDA compact path's separate
        lora_up / lora_down workspaces."""
        ws = self.lora_ws
        assert ws is not None
        return ws.scratch.get(
            (ws.max_mprime, int(rank)), device=device, dtype=dtype
        )


def prepare_compact_mps(
    spec: MoeSpec,
    capacity: MoeCapacity,
    device: torch.device,
) -> CompactMpsMoeImpl:
    if device.type != "mps":
        raise ValueError("prepare_compact_mps requires an MPS device")
    if spec.weight_format != "fp8_e4m3":
        raise NotImplementedError(
            "kestrel-kernels MPS MoE is FP8-only; got weight_format="
            f"{spec.weight_format!r}"
        )
    # block_m=64 (prefill) aligns experts to tiles (pad); block_m=8 (decode)
    # packs across experts. See the per-regime analysis in the route kernel.
    block_m = _pick_block_m(capacity.max_tokens)
    pad_experts = block_m == 64
    decode_gemv_max_tokens = 0
    if block_m == 8 and hasattr(_native.ops, "moe_fp8_decode_gemv_max_tokens"):
        up_limit = int(_native.ops.moe_fp8_decode_gemv_max_tokens(
            spec.hidden_size, spec.intermediate_size * 2,
        ))
        down_limit = int(_native.ops.moe_fp8_decode_gemv_max_tokens(
            spec.intermediate_size, spec.hidden_size,
        ))
        decode_gemv_max_tokens = min(up_limit, down_limit)
    max_mprime = _mprime(
        capacity.max_tokens * spec.top_k, block_m, spec.num_experts, pad_experts
    )
    route = _CompactMpsRoute(
        sorted_token_ids=torch.empty(
            (max_mprime,), dtype=torch.int32, device=device
        ),
        rhs_indices=torch.empty(
            (max_mprime,), dtype=torch.int32, device=device
        ),
    )
    workspace = _CompactMpsWorkspace(
        up=FixedWorkspaceBuffer("MoE MPS up workspace"),
        activation=FixedWorkspaceBuffer("MoE MPS activation workspace"),
        down=FixedWorkspaceBuffer("MoE MPS down workspace"),
        output=FixedWorkspaceBuffer("MoE MPS output workspace"),
    )
    workspace.up.reserve(
        (capacity.max_tokens, spec.top_k, spec.intermediate_size * 2),
        device=device, dtype=spec.dtype,
    )
    workspace.activation.reserve(
        (capacity.max_tokens * spec.top_k, spec.intermediate_size),
        device=device, dtype=spec.dtype,
    )
    workspace.down.reserve(
        (capacity.max_tokens, spec.top_k, spec.hidden_size),
        device=device, dtype=spec.dtype,
    )
    workspace.output.reserve(
        (capacity.max_tokens, spec.hidden_size),
        device=device, dtype=spec.dtype,
    )

    lora_ws = None
    if capacity.max_loras > 0 and capacity.max_lora_rank > 0:
        # LoRA route is dense (pad_experts=False) regardless of block_m, so the
        # worst-case extent is just the active assignments rounded to block_m.
        max_lora_mprime = _max_lora_mprime(
            capacity.max_tokens, spec.top_k, spec.num_experts,
            capacity.max_loras, block_m, pad_experts=False,
        )
        scratch = FixedWorkspaceBuffer("MoE MPS LoRA scratch workspace")
        scratch.reserve(
            (max_lora_mprime, capacity.max_lora_rank),
            device=device, dtype=spec.dtype,
        )
        lora_ws = _CompactMpsLoraWorkspace(
            route_sorted=torch.empty(
                (max_lora_mprime,), dtype=torch.int32, device=device
            ),
            route_rhs=torch.empty(
                (max_lora_mprime,), dtype=torch.int32, device=device
            ),
            scratch=scratch,
            max_mprime=max_lora_mprime,
        )

    return CompactMpsMoeImpl(
        spec=spec,
        capacity=capacity,
        device=device,
        block_m=block_m,
        pad_experts=pad_experts,
        route=route,
        workspace=workspace,
        lora_ws=lora_ws,
        decode_gemv_max_tokens=decode_gemv_max_tokens,
    )


__all__ = [
    "CompactMpsMoeImpl",
    "gelu_residual_cute_mps",
    "moe_lora_route_compact_mps",
    "moe_route_compact_mps",
    "moe_sum_mps",
    "prepare_compact_mps",
    "topk_fwd_mps",
]
